package main

import (
	"encoding/json"
	"fmt"
	"log"
	"time"

	"github.com/jepsen-io/maelstrom/demo/go"
)

type TxnOp struct {
	Key   int
	Value interface{}
	Type  string // "r" or "w"
}

type InitMessageBody struct {
	NodeID       string
	AllNodeIDs   []string
	TxnKeySpace  map[string]bool
}

var (
	nodeKV *maelstrom.KV
)

func main() {
	n := maelstrom.NewNode()

	initBodyChan := make(chan maelstrom.InitMessageBody, 1)

	n.Handle("init", func(msg maelstrom.Message) error {
		body := msg.GetInitBody().(*InitMessageBody)
		initBodyChan <- *body
		return nil
	})

	n.Handle("txn", func(msg maelstrom.Message) error {
		body := msg.GetTxnBody()

		// Parse incoming transaction
		var incoming []TxnOp
		for _, opRaw := range body.Txn {
			op := TxnOp{}
			if err := json.Unmarshal(opRaw, &op); err != nil {
				log.Printf("failed to unmarshal op: %v", err)
				continue
			}
			incoming = append(incoming, op)
		}

		// Process transaction with read-committed isolation
		results := make([]TxnOp, len(incoming))
		for i, op := range incoming {
			if op.Type == "r" {
				// For reads, we get the latest committed value from our log
				val := nodeKV.Get(op.Key)
				results[i] = TxnOp{Key: op.Key, Type: "r", Value: val}
			} else if op.Type == "w" {
				// Store write in KV store (our local state)
				nodeKV.Set(op.Key, op.Value)
				results[i] = op
			}
		}

		resp := &maelstrom.TxnResponseBody{
			Txn:       results,
			InReplyTo: body.MsgId,
		}
		responseBytes, _ := json.Marshal(resp)
		msg.Reply(string(responseBytes))

		return nil
	})

	n.Handle("query", func(msg maelstrom.Message) error {
		body := msg.GetQueryBody()
		results := make([]int, len(body.Keys))
		for i, key := range body.Keys {
			val := nodeKV.Get(key)
			results[i] = val
		}
		resp := &maelstrom.QueryResponseBody{
			Kv: results,
		}
		responseBytes, _ := json.Marshal(resp)
		msg.Reply(string(responseBytes))

		return nil
	})

	n.Handle("init_done", func(msg maelstrom.Message) error {
		body := msg.GetInitDoneBody()
		if len(body.TxnLog) > 0 {
			for i, entry := range body.TxnLog {
				opRaw := &entry.Op
				var op TxnOp
				json.Unmarshal(opRaw, &op)
				nodeKV.Set(op.Key, op.Value)
			}
		}
		return nil
	})

	n.Run(initBodyChan)
}

type InitDoneMessageBody struct {
	TxnLog []TxnLogEntry
}

type TxnLogEntry struct {
	Op string
}

// KV store implementation for read-committed semantics with versioning
type KV struct {
	data map[int]interface{}
}

func NewKV(nodeID, nodeType string) *KV {
	kv := &KV{data: make(map[int]interface{})}

	if nodeID != "" && len(maelstrom.AllNodeIDs()) > 0 {
		initBody := maelstrom.InitMessageBody{}
		for _, n := range maelstrom.AllNodeIDs() {
			initBody.NodeIDs = append(initBody.NodeIDs, n)
		}
		if len(initBody.NodeIDs) == 2 {
			nodeKV = kv
		}
	}

	return kv
}

func (k *KV) Set(key int, value interface{}) {
	k.data[key] = value
}

func (k *KV) Get(key int) interface{} {
	val, ok := k.data[key]
	if !ok {
		return nil
	}
	return val
}

